1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	  <meta charset="UTF-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
6	  <meta name="color-scheme" content="light dark">
7	  <title>Animated Circle - Interactive Demo</title>
8	  <meta name="description" content="A responsive, accessible circle that changes color when clicked">
9	  <style>
10	    *,
11	    *::before,
12	    *::after {
13	      box-sizing: border-box;
14	      margin: 0;
15	      padding: 0;
16	    }
17	    :root {
18	      color-scheme: light dark;
19	      --bg: #fff;
20	      --text: #374151;
21	      --fg: #2563eb;
22	      --shadow: rgba(0, 0, 0, 0.1);
23	      --kbd-bg: rgba(0, 0, 0, 0.1);
24	    }
25	    [data-color="red"] { --fg: #dc2626; }
26	    [data-color="green"] { --fg: #16a34a; }
27	    [data-color="amber"] { --fg: #d97706; }
28	    [data-color="violet"] { --fg: #7c3aed; }
29	    [data-color="cyan"] { --fg: #0891b2; }
30	    @media (prefers-color-scheme: dark) {
31	      :root {
32	        --bg: #111;
33	        --text: #d1d5db;
34	        --fg: #93c5fd;
35	        --shadow: rgba(0, 0, 0, 0.6);
36	        --kbd-bg: rgba(255, 255, 255, 0.15);
37	      }
38	      [data-color="red"] { --fg: #fca5a5; }
39	      [data-color="green"] { --fg: #86efac; }
40	      [data-color="amber"] { --fg: #fcd34d; }
41	      [data-color="violet"] { --fg: #c4b5fd; }
42	      [data-color="cyan"] { --fg: #67e8f9; }
43	    }
44	    @media (prefers-contrast: more) {
45	      :root {
46	        --shadow: rgba(0, 0, 0, 0.9);
47	      }
48	      .hint {
49	        opacity: 1;
50	      }
51	    }
52	    @media (forced-colors: active) {
53	      svg circle {
54	        stroke: CanvasText;
55	        stroke-width: 2;
56	      }
57	    }
58	    body {
59	      min-height: 100vh;
60	      min-height: 100dvh;
61	      display: grid;
62	      place-items: center;
63	      padding: 1rem;
64	      background: var(--bg);
65	      color: var(--text);
66	      font-family: system-ui, -apple-system, sans-serif;
67	    }
68	    main {
69	      width: 100%;
70	      display: flex;
71	      flex-direction: column;
72	      align-items: center;
73	      text-align: center;
74	    }
75	    button {
76	      display: block;
77	      width: min(360px, 100%, 60vh);
78	      aspect-ratio: 1;
79	      border: 0;
80	      border-radius: 50%;
81	      background: none;
82	      color: var(--fg);
83	      cursor: pointer;
84	      touch-action: manipulation;
85	      -webkit-tap-highlight-color: transparent;
86	      transition: color 0.4s ease;
87	    }
88	    .no-transition,
89	    .no-transition svg {
90	      transition: none !important;
91	    }
92	    button:focus-visible {
93	      outline: 3px solid var(--fg);
94	      outline-offset: 8px;
95	    }
96	    svg {
97	      display: block;
98	      width: 100%;
99	      height: 100%;
100	      overflow: visible;
101	      opacity: 0.9;
102	      filter: drop-shadow(0 8px 16px var(--shadow));
103	      transition: opacity 0.3s ease;
104	    }
105	    button:active svg,
106	    button:focus-visible svg {
107	      opacity: 1;
108	    }
109	    @keyframes pulse {
110	      0% {
111	        filter: drop-shadow(0 8px 16px var(--shadow)) drop-shadow(0 0 20px var(--fg));
112	      }
113	      100% {
114	        filter: drop-shadow(0 8px 16px var(--shadow));
115	      }
116	    }
117	    @media (hover: hover) {
118	      button:hover svg {
119	        opacity: 1;
120	      }
121	    }
122	    @media (prefers-reduced-motion: no-preference) {
123	      svg {
124	        transition:
125	          transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1),
126	          opacity 0.3s ease;
127	      }
128	      button:focus-visible svg {
129	        transform: scale(1.05);
130	      }
131	      button:active svg {
132	        transform: scale(0.97);
133	      }
134	      button.color-changed svg {
135	        animation: pulse 0.5s ease-out;
136	      }
137	    }
138	    @media (hover: hover) and (prefers-reduced-motion: no-preference) {
139	      button:hover:not(:active) svg {
140	        transform: scale(1.05);
141	      }
142	    }
143	    .status {
144	      margin-top: 2rem;
145	      font-weight: 600;
146	    }
147	    .hint {
148	      margin-top: 0.25rem;
149	      font-size: 0.875rem;
150	      opacity: 0.8;
151	    }
152	    kbd {
153	      display: inline-block;
154	      padding: 0.125rem 0.375rem;
155	      background: var(--kbd-bg);
156	      border: 1px solid transparent;
157	      border-radius: 0.25rem;
158	      font-family: monospace;
159	      font-size: 0.75em;
160	    }
161	  </style>
162	</head>
163	<body>
164	  <main>
165	    <button type="button" class="no-transition" aria-label="Change circle color" aria-describedby="status hint">
166	      <svg viewBox="0 0 100 100" aria-hidden="true" focusable="false" xmlns="http://www.w3.org/2000/svg">
167	        <circle cx="50" cy="50" r="50" fill="currentColor"/>
168	      </svg>
169	    </button>
170	    <p class="status" id="status" role="status">Blue</p>
171	    <p class="hint" id="hint"><span class="verb">Click</span> to change color (or press <kbd>Space</kbd> or <kbd>Enter</kbd>; hold <kbd>Shift</kbd> to go back)</p>
172	  </main>
173	  <script>
174	    const button = document.querySelector('button');
175	    const status = document.querySelector('.status');
176	    const colors = ['blue', 'red', 'green', 'amber', 'violet', 'cyan'];
177	    const storageKey = 'circle-color';
178	
179	    function loadColor() {
180	      try {
181	        return localStorage.getItem(storageKey);
182	      } catch {
183	        return null;
184	      }
185	    }
186	
187	    function saveColor(color) {
188	      try {
189	        localStorage.setItem(storageKey, color);
190	      } catch {}
191	    }
192	
193	    let index = Math.max(colors.indexOf(loadColor()), 0);
194	
195	    function applyColor() {
196	      const color = colors[index];
197	      if (color === 'blue') {
198	        delete button.dataset.color;
199	      } else {
200	        button.dataset.color = color;
201	      }
202	      status.textContent = color[0].toUpperCase() + color.slice(1);
203	    }
204	
205	    function changeColor(event) {
206	      const step = event.shiftKey ? -1 : 1;
207	      index = (index + step + colors.length) % colors.length;
208	      applyColor();
209	      saveColor(colors[index]);
210	
211	      button.classList.remove('color-changed');
212	      void button.offsetWidth;
213	      button.classList.add('color-changed');
214	    }
215	
216	    applyColor();
217	    requestAnimationFrame(() => {
218	      requestAnimationFrame(() => button.classList.remove('no-transition'));
219	    });
220	
221	    if (matchMedia('(hover: none)').matches) {
222	      document.querySelector('.hint .verb').textContent = 'Tap';
223	    }
224	
225	    button.addEventListener('click', changeColor);
226	    button.addEventListener('animationend', () => {
227	      button.classList.remove('color-changed');
228	    });
229	  </script>
230	</body>
231	</html>
